// Development-only actual fixed Go JSON and ProtoJSON double-consumer oracle.
package main
import("bufio";"encoding/base64";"encoding/json";"fmt";"math";"os";"strconv";"github.com/livekit/protocol/livekit";"google.golang.org/protobuf/encoding/protojson";"google.golang.org/protobuf/proto")
func main(){s:=bufio.NewScanner(os.Stdin);enc:=json.NewEncoder(os.Stdout);for s.Scan(){var in struct{Name string `json:"name"`;Lexeme string `json:"lexeme"`};if err:=json.Unmarshal(s.Bytes(),&in);err!=nil{panic(err)};row:=map[string]any{"name":in.Name,"lexeme":in.Lexeme};f,err:=strconv.ParseFloat(in.Lexeme,64);if err!=nil{row["strconv_error"]=err.Error()}else{row["strconv_bits"]=fmt.Sprintf("%016x",math.Float64bits(f))};var value float64;if err:=json.Unmarshal([]byte(in.Lexeme),&value);err!=nil{row["json_error"]=err.Error()}else{row["json_bits"]=fmt.Sprintf("%016x",math.Float64bits(value))};var msg livekit.EncodingOptions;body:=[]byte(`{"key_frame_interval":`+in.Lexeme+`}`);if err:=protojson.Unmarshal(body,&msg);err!=nil{row["protojson_error"]=err.Error()}else{row["protojson_bits"]=fmt.Sprintf("%016x",math.Float64bits(msg.KeyFrameInterval));wire,err:=proto.Marshal(&msg);if err!=nil{panic(err)};row["wire_base64"]=base64.StdEncoding.EncodeToString(wire)};if err:=enc.Encode(row);err!=nil{panic(err)}};if err:=s.Err();err!=nil{panic(err)}}
